//! Loads the golden vectors in `tests/golden/*.json` (generated by `tools/golden/gen.mjs` with
//! ffjavascript, an implementation independent of arkworks and of this library) into the GPU's
//! plain `u32`-word format. Shared by the native and the browser tests.
use serde_json::Value;

pub struct NttCase {
    pub log_n: u32,
    pub inverse: bool,
    pub input: Vec<u32>,
    pub output: Vec<u32>,
}

pub struct MsmCase {
    pub name: String,
    pub bases: Vec<u32>,   // 16 words per point: x then y; infinity is (0, 0)
    pub scalars: Vec<u32>, // 8 words per scalar
    pub result: Vec<u32>,  // 16 words: x then y; infinity is (0, 0)
}

/// Big-endian hex string -> 8 little-endian u32 words.
fn words(hex: &str) -> [u32; 8] {
    assert!(hex.len() <= 64, "value wider than 256 bits");
    let padded = format!("{hex:0>64}");
    std::array::from_fn(|i| u32::from_str_radix(&padded[64 - 8 * (i + 1)..64 - 8 * i], 16).expect("bad hex"))
}

fn flat(values: &Value) -> Vec<u32> {
    values.as_array().unwrap().iter().flat_map(|v| words(v.as_str().unwrap())).collect()
}

fn cases(json: &str) -> Vec<Value> {
    serde_json::from_str::<Value>(json).unwrap()["cases"].as_array().unwrap().clone()
}

pub fn ntt_cases() -> Vec<NttCase> {
    cases(include_str!("../golden/ntt.json"))
        .iter()
        .map(|c| NttCase {
            log_n: c["log_n"].as_u64().unwrap() as u32,
            inverse: c["direction"] == "inverse",
            input: flat(&c["input"]),
            output: flat(&c["output"]),
        })
        .collect()
}

pub fn msm_cases() -> Vec<MsmCase> {
    cases(include_str!("../golden/msm.json"))
        .iter()
        .map(|c| MsmCase {
            name: c["name"].as_str().unwrap().to_string(),
            bases: c["bases"].as_array().unwrap().iter().flat_map(flat).collect(),
            scalars: flat(&c["scalars"]),
            result: flat(&c["result"]),
        })
        .collect()
}
